<script setup lang="ts">import type{OperationsCase}from"~/composables/useContentOperations";defineProps<{item:OperationsCase}>();defineEmits<{action:[kind:"claim"|"release"|"escalate",item:OperationsCase]}>();</script>
<template><article class="operations-case"><header><div><p>پرونده {{item.id.slice(0,8)}}</p><h2>{{item.title}}</h2></div><SlaClock :due-at="item.sla_due_at" :state="item.sla_state"/></header><dl><div><dt>سطح ریسک</dt><dd>{{item.risk_band}}</dd></div><div><dt>گزارش‌ها</dt><dd>{{item.report_count.toLocaleString('fa-IR')}}</dd></div><div><dt>سطح تشدید</dt><dd>{{item.escalation_level.toLocaleString('fa-IR')}}</dd></div><div><dt>تخصیص</dt><dd>{{item.claimed_by||'بدون کارشناس'}}</dd></div></dl><section><h3>شواهد و رویدادها</h3><ol class="case-timeline"><li>گزارش کاربر دریافت و اثرانگشت شد.</li><li>ریسک و SLA بر اساس سیاست فعال محاسبه شد.</li><li v-if="item.claimed_by">پرونده با lease محدود تخصیص یافته است.</li></ol></section><footer><button v-if="item.state!=='claimed'" class="primary-button compact" @click="$emit('action','claim',item)">دریافت پرونده</button><button v-else class="secondary-button compact" @click="$emit('action','release',item)">بازگرداندن به صف</button><button class="secondary-button compact" @click="$emit('action','escalate',item)">تشدید به سرپرست</button></footer></article></template>

